 if(owner.job){SatchelVulkanSubmissionReport done={0};r->backend_status=satchel_vulkan_submission_wait(owner.device,owner.job,0,NULL,NULL,&done);if(r->backend_status!=SATCHEL_VULKAN_OK||!done.completed||done.resources_retained)return 0;owner.job=0;}
 for(unsigned i=0;i<2;i++)if(owner.pipeline[i]){r->backend_status=satchel_vulkan_raster_destroy(owner.device,owner.pipeline[i]);if(r->backend_status!=SATCHEL_VULKAN_OK)return 0;owner.pipeline[i]=0;}
