 if(owner.target){r->backend_status=satchel_vulkan_target_destroy(owner.device,owner.target);if(r->backend_status!=SATCHEL_VULKAN_OK)return 0;owner.target=0;}
 if(owner.device){r->backend_status=satchel_vulkan_device_destroy(owner.device);if(r->backend_status!=SATCHEL_VULKAN_OK)return 0;owner.device=0;r->device_finalized=1;}
