static SatchelCFState original_state(void){return(SatchelCFState){.known=255,.single_vertex_program=1,.viewport_transform_enabled=1,.depth_zero_to_one=1,.origin_upper_left=1,.alpha_test_always=1,.extra_known=4095,.topology=3,.point_size_bits=0x3f800000,.float_vertex_mask=3,.float_output_mask=1};}
