 r->stage=4;original(0,0);SatchelCapturedRequest request={0};request.version=1;request.size=sizeof(request);request.vertex=(SatchelCFSource){vs,vs+80,80,56};request.fragment=(SatchelCFSource){fs,fs+80,80,56};request.state=original_state();request.max_work=65536;request.timeout_ns=1000000000;request.cancelled=poll;request.context=p;SatchelCFPairV2 result={0};r->compiler_status=satchel_captured_compile_for_target(owner.device,owner.target,&request,&result,sizeof(result));REQUIRE(r->compiler_status==0&&result.proven_source_unused==6&&!result.pair.dynamic_code_features);r->pairs_compiled++;
