 done:if(!cleanup(&r)&&r.status==SATCHEL_GUEST_PROVOKING_OK)r.status=SATCHEL_GUEST_PROVOKING_BUSY;r.resources_retained=pending();if(!snapshot(&r.final))r.status=SATCHEL_GUEST_PROVOKING_FAILED;r.cleanup_matched=!r.resources_retained&&!memcmp(&r.baseline,&r.final,sizeof(r.baseline));if(r.status==SATCHEL_GUEST_PROVOKING_OK){if(r.cleanup_matched)r.stage=10;else r.status=SATCHEL_GUEST_PROVOKING_FAILED;}*out=r;atomic_flag_clear(&active);return r.status;
